 * Get all reviews for a sucursal, newest first.
 */
export const obtenerReviews = (sucursalId) => {
    return leerReviews()
        .filter(r => r.sucursalId === sucursalId)
        .sort((a, b) => new Date(b.fecha) - new Date(a.fecha));
};

